#!/usr/bin/env pwsh
# Genera src/assets/version.json con la version funcional (release.config.json)
# combinada con los datos tecnicos del build de Azure DevOps.
#
# Se ejecuta en el AGENTE, ANTES del docker build (Task group: Build).
# El `COPY . .` del Dockerfile arrastra el archivo y `ng build` lo copia a
# dist/assets/version.json, que la app sirve en /assets/version.json.
#
# Lee las variables predefinidas de Azure DevOps via variables de entorno:
#   BUILD_SOURCESDIRECTORY, BUILD_BUILDID, BUILD_BUILDNUMBER,
#   BUILD_SOURCEVERSION, BUILD_SOURCEBRANCHNAME, BUILD_SOURCEBRANCH,
#   BUILD_DEFINITIONNAME, AMBIENTE
# Permite override por parametro para pruebas locales.

[CmdletBinding()]
param(
  [string]$SourcesDirectory = $(if ($env:BUILD_SOURCESDIRECTORY) { $env:BUILD_SOURCESDIRECTORY } else { (Get-Location).Path }),
  [string]$Environment      = $env:AMBIENTE,
  [string]$BuildId          = $env:BUILD_BUILDID,
  [string]$BuildNumber      = $env:BUILD_BUILDNUMBER,
  [string]$Commit           = $env:BUILD_SOURCEVERSION,
  [string]$BranchName       = $env:BUILD_SOURCEBRANCHNAME,
  [string]$SourceBranch     = $env:BUILD_SOURCEBRANCH,
  [string]$PipelineName     = $env:BUILD_DEFINITIONNAME
)

$ErrorActionPreference = 'Stop'

$releaseConfigPath = Join-Path $SourcesDirectory 'release.config.json'
$assetsReleasePath = Join-Path $SourcesDirectory 'src/assets/release.config.json'
$versionOutputPath = Join-Path $SourcesDirectory 'src/assets/version.json'

# 1. release.config.json debe existir (fuente de la version funcional, controlada en git)
if (-not (Test-Path $releaseConfigPath)) {
  throw "No se encontro release.config.json en la raiz del repositorio ($releaseConfigPath)."
}

# 2. Leer y validar release.config.json (fallback local + baseline documentado)
try {
  $releaseConfig = Get-Content $releaseConfigPath -Raw | ConvertFrom-Json
} catch {
  throw "release.config.json no es un JSON valido: $($_.Exception.Message)"
}

$configVersion = $releaseConfig.version
if ([string]::IsNullOrWhiteSpace($configVersion)) {
  throw "release.config.json no contiene la propiedad 'version' o viene vacia."
}
if ($configVersion -notmatch '^\d+\.\d+\.\d+$') {
  throw "La version '$configVersion' de release.config.json no cumple el formato SemVer MAJOR.MINOR.PATCH."
}

# 3. Resolver la version efectiva (Opcion B: auto-incremento del patch)
#    El pipeline define el Build number como $(major).$(minor).$(Rev:r),
#    asi que Build.BuildNumber ya viene como SemVer con el patch auto-incrementado
#    (1.0.1, 1.0.2, ... y resetea al subir major/minor). Esa es la fuente cuando aplica.
#    En dev local (sin build number SemVer) cae al valor de release.config.json.
if ($BuildNumber -match '^\d+\.\d+\.\d+$') {
  $appVersion = $BuildNumber
  Write-Host "Version efectiva desde Build.BuildNumber (patch auto-incrementado): $appVersion"
} else {
  $appVersion = $configVersion
  Write-Host "Version efectiva desde release.config.json (fallback): $appVersion"
}

# 4. Resolver ambiente: variable 'ambiente' del pipeline > branch
if ([string]::IsNullOrWhiteSpace($Environment)) {
  $Environment = $BranchName
}
if ([string]::IsNullOrWhiteSpace($Environment)) {
  $Environment = 'unknown'
}

# 5. Commit corto
$shortCommit = $Commit
if ($Commit -and $Commit.Length -gt 8) {
  $shortCommit = $Commit.Substring(0, 8)
}

$publishedAt = (Get-Date).ToUniversalTime().ToString("yyyy-MM-ddTHH:mm:ssZ")

# 6. Construir version.json (calza con AppVersionInfo del frontend)
$versionInfo = [ordered]@{
  app          = 'buklo-web'
  environment  = $Environment
  version      = $appVersion
  release      = $BuildNumber
  buildId      = $BuildId
  buildNumber  = $BuildNumber
  commit       = $shortCommit
  branch       = $BranchName
  sourceBranch = $SourceBranch
  pipeline     = $PipelineName
  publishedAt  = $publishedAt
}

$versionJson = $versionInfo | ConvertTo-Json -Depth 10

# 7. Escribir version.json
$assetsDir = Split-Path $versionOutputPath
if (-not (Test-Path $assetsDir)) {
  New-Item -ItemType Directory -Path $assetsDir -Force | Out-Null
}
# UTF-8 sin BOM en ambas ediciones (Windows PowerShell 5.1 y PowerShell Core):
# un BOM al inicio rompe JSON.parse en el navegador.
$utf8NoBom = New-Object System.Text.UTF8Encoding($false)
[System.IO.File]::WriteAllText($versionOutputPath, $versionJson, $utf8NoBom)

# 8. Mantener src/assets/release.config.json sincronizado con la raiz
#    (asi el fallback del frontend nunca queda desfasado de la fuente)
if (Test-Path $assetsReleasePath) {
  Copy-Item $releaseConfigPath $assetsReleasePath -Force
}

Write-Host "version.json generado en: $versionOutputPath"
Write-Host $versionJson

# ---------------------------------------------------------------------------
# 9. Validacion post-generacion: confirmar que quedo bien y previsualizar la UI
# ---------------------------------------------------------------------------
Write-Host ""
Write-Host "=== Validacion de version.json ==="

if (-not (Test-Path $versionOutputPath)) {
  throw "No se genero src/assets/version.json. Se detiene el build."
}

try {
  $generated = Get-Content $versionOutputPath -Raw | ConvertFrom-Json
} catch {
  throw "El version.json generado no es un JSON valido: $($_.Exception.Message)"
}

# Campos obligatorios para trazabilidad (deben venir poblados desde Azure DevOps)
$requiredFields = @('app', 'environment', 'version', 'release', 'buildId', 'buildNumber', 'commit', 'branch', 'publishedAt')
$missing = @()
foreach ($field in $requiredFields) {
  if ([string]::IsNullOrWhiteSpace([string]$generated.$field)) {
    $missing += $field
  }
}
if ($missing.Count -gt 0) {
  throw "version.json incompleto. Campos vacios: $($missing -join ', '). Revisar las variables del pipeline."
}

Write-Host "OK - JSON valido y con todos los campos requeridos."

# Previsualizar como lo mostrara el frontend (replica de AppVersionService)
switch -Regex ($generated.environment.ToLower()) {
  '^(uat)$'              { $envTag = 'UAT'; break }
  '^(production|prod)$'  { $envTag = 'PROD'; break }
  default                { $envTag = 'DEV' }
}
$shortCommit7 = if ($generated.commit.Length -gt 7) { $generated.commit.Substring(0, 7) } else { $generated.commit }
$build = if ($generated.buildNumber) { $generated.buildNumber } else { $generated.release }

$technicalBadge = "$envTag . v$($generated.version) . build $build . $shortCommit7"
$simpleLabel    = "Version $($generated.version)"
$compactLabel   = "v$($generated.version)"

Write-Host ""
Write-Host "=== Como se mostrara en la UI ==="
Write-Host "  Badge tecnico (DEV/UAT):     $technicalBadge"
Write-Host "  Etiqueta simple (PROD):      $simpleLabel"
Write-Host "  Etiqueta compacta (login):   $compactLabel"
Write-Host "==================================="

